    12  bool OpenTypeMAXP::Parse(const uint8_t *data, size_t length) {
    13    Buffer table(data, length);
    14
    15    uint32_t version = 0;
    16    if (!table.ReadU32(&version)) {
    17      return Error("Failed to read table version");
    18    }
    19
    20    if (version >> 16 > 1) {
    21      return Error("Unsupported table version 0x%x", version);
    22    }
    23
    24    if (!table.ReadU16(&this->num_glyphs)) {
    25      return Error("Failed to read numGlyphs");
    26    }
    27
    28    if (!this->num_glyphs) {
    29      return Error("numGlyphs is 0");
    30    }
    31
    32    if (version >> 16 == 1) {
    33      this->version_1 = true;
    34      if (!table.ReadU16(&this->max_points) ||
    35          !table.ReadU16(&this->max_contours) ||
    36          !table.ReadU16(&this->max_c_points) ||
    37          !table.ReadU16(&this->max_c_contours) ||
    38          !table.ReadU16(&this->max_zones) ||
    39          !table.ReadU16(&this->max_t_points) ||
    40          !table.ReadU16(&this->max_storage) ||
    41          !table.ReadU16(&this->max_fdefs) ||
    42          !table.ReadU16(&this->max_idefs) ||
    43          !table.ReadU16(&this->max_stack) ||
    44          !table.ReadU16(&this->max_size_glyf_instructions) ||
    45          !table.ReadU16(&this->max_c_components) ||
    46          !table.ReadU16(&this->max_c_depth)) {
    47        return Error("Failed to read version 1 table data");
    48      }
    49
    50      if (this->max_zones == 0) {
    51        // workaround for ipa*.ttf Japanese fonts.
    52        Warning("Bad maxZones: %u", this->max_zones);
    53        this->max_zones = 1;
    54      } else if (this->max_zones == 3) {
    55        // workaround for Ecolier-*.ttf fonts.
    56        Warning("Bad maxZones: %u", this->max_zones);
    57        this->max_zones = 2;
    58      }
    59
    60      if ((this->max_zones != 1) && (this->max_zones != 2)) {
    61        return Error("Bad maxZones: %u", this->max_zones);
    62      }
    63    } else {
    64      this->version_1 = false;
    65    }
    66
    67    return true;
    68  }
