    70  bool OpenTypeMAXP::Serialize(OTSStream *out) {
    71    if (!out->WriteU32(this->version_1 ? 0x00010000 : 0x00005000) ||
    72        !out->WriteU16(this->num_glyphs)) {
    73      return Error("Failed to write version or numGlyphs");
    74    }
    75
    76    if (!this->version_1) return true;
    77
    78    if (!out->WriteU16(this->max_points) ||
    79        !out->WriteU16(this->max_contours) ||
    80        !out->WriteU16(this->max_c_points) ||
    81        !out->WriteU16(this->max_c_contours)) {
    82      return Error("Failed to write maxp");
    83    }
    84
    85    if (!out->WriteU16(this->max_zones) ||
    86        !out->WriteU16(this->max_t_points) ||
    87        !out->WriteU16(this->max_storage) ||
    88        !out->WriteU16(this->max_fdefs) ||
    89        !out->WriteU16(this->max_idefs) ||
    90        !out->WriteU16(this->max_stack) ||
    91        !out->WriteU16(this->max_size_glyf_instructions)) {
    92      return Error("Failed to write more maxp");
    93    }
    94
    95    if (!out->WriteU16(this->max_c_components) ||
